{
  "name": "life-estate",
  "private": true,
  "version": "1.0.0",
  "description": "Life Estate - a living 3D board game where every property is a colony.",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0",
    "test": "node --test tests/*.test.js",
    "sim": "node scripts/simulate.js",
    "android:assets": "npm run build && node scripts/sync-android-assets.js",
    "android:debug": "npm run android:assets && cd android && ./gradlew assembleDebug",
    "android:bundle": "npm run android:assets && cd android && ./gradlew bundleRelease",
    "android:install": "adb install -r android/app/build/outputs/apk/debug/app-debug.apk"
  },
  "dependencies": {
    "@fontsource-variable/fraunces": "^5.3.0",
    "@fontsource-variable/outfit": "^5.3.0",
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^8.3.5"
  }
}

import { defineConfig } from 'vite'

export default defineConfig({
  base: './',
  build: {
    target: 'es2020',
    assetsInlineLimit: 4096,
    chunkSizeWarningLimit: 1200
  },
  server: {
    port: 3002,
    strictPort: false
  }
})

/**
 * Conway's Game of Life on a torus, with a small "immigration" rule so a
 * property never becomes permanently dead. Pure functions only.
 */

import { PATTERNS } from './constants.js'

export function emptyGrid(size) {
  return new Uint8Array(size * size)
}

export function cloneGrid(grid) {
  return Uint8Array.from(grid)
}

export function population(grid) {
  let n = 0
  for (let i = 0; i < grid.length; i++) n += grid[i] ? 1 : 0
  return n
}

export function idx(size, x, y) {
  return ((y % size) + size) % size * size + (((x % size) + size) % size)
}

export function isAlive(grid, size, x, y) {
  return grid[idx(size, x, y)] === 1
}

export function toggleCell(grid, size, x, y) {
  const i = idx(size, x, y)
  grid[i] = grid[i] ? 0 : 1
  return grid[i] === 1
}

export function liveNeighbours(grid, size, x, y) {
  let n = 0
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue
      if (isAlive(grid, size, x + dx, y + dy)) n++
    }
  }
  return n
}

/**
 * Advance one generation. Returns the next grid plus a small change report
 * which the renderer uses for birth/death animations.
 */
export function stepLife(grid, size, rng = Math.random, options = {}) {
  const next = emptyGrid(size)
  const born = []
  const died = []
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = y * size + x
      const alive = grid[i] === 1
      const n = liveNeighbours(grid, size, x, y)
      const lives = alive ? n === 2 || n === 3 : n === 3
      if (lives) {
        next[i] = 1
        if (!alive) born.push(i)
      } else if (alive) {
        died.push(i)
      }
    }
  }

  let pop = population(next)
  if (options.immigration !== false) {
    // A tiny amount of spontaneous life keeps colonies from flat-lining and
    // makes every property worth visiting. It is deliberately rare.
    if (pop === 0) {
      const a = randomEmpty(next, rng)
      const b = randomEmpty(next, rng)
      if (a >= 0) next[a] = 1
      if (b >= 0) next[b] = 1
      pop += (a >= 0 ? 1 : 0) + (b >= 0 ? 1 : 0)
    } else if (pop <= 2 && rng() < 0.45) {
      const a = randomEmpty(next, rng)
      if (a >= 0) {
        next[a] = 1
        pop++
      }
    }
  }
  return { grid: next, born, died, population: pop }
}

export function randomEmpty(grid, rng = Math.random) {
  const empty = []
  for (let i = 0; i < grid.length; i++) if (!grid[i]) empty.push(i)
  if (!empty.length) return -1
  return empty[Math.floor(rng() * empty.length)]
}

export function randomLive(grid, rng = Math.random) {
  const live = []
  for (let i = 0; i < grid.length; i++) if (grid[i]) live.push(i)
  if (!live.length) return -1
  return live[Math.floor(rng() * live.length)]
}

export function addCells(grid, size, count, rng = Math.random, candidates = null) {
  let added = 0
  for (let tries = 0; tries < count * 12 && added < count; tries++) {
    let i
    if (candidates && candidates.length) {
      i = candidates[Math.floor(rng() * candidates.length)]
      if (grid[i]) continue
    } else {
      i = randomEmpty(grid, rng)
    }
    if (i < 0) break
    grid[i] = 1
    added++
  }
  return added
}

export function removeCells(grid, size, count, rng = Math.random) {
  let removed = 0
  for (let tries = 0; tries < count * 12 && removed < count; tries++) {
    const i = randomLive(grid, rng)
    if (i < 0) break
    grid[i] = 0
    removed++
  }
  return removed
}

export function placePattern(grid, size, name, rng = Math.random, offsetX = null, offsetY = null) {
  const pattern = typeof name === 'string' ? PATTERNS[name] : name
  if (!pattern) return 0
  const width = Math.max(...pattern.map(([x]) => x)) + 1
  const height = Math.max(...pattern.map(([, y]) => y)) + 1
  const ox = offsetX == null ? Math.floor((size - width) / 2) : offsetX
  const oy = offsetY == null ? Math.floor((size - height) / 2) : offsetY
  let added = 0
  for (const [x, y] of pattern) {
    const tx = ((ox + x) % size + size) % size
    const ty = ((oy + y) % size + size) % size
    const i = ty * size + tx
    if (!grid[i]) {
      grid[i] = 1
      added++
    }
  }
  return added
}

export function seedColony(size, pattern = 'rpent', rng = Math.random) {
  const grid = emptyGrid(size)
  placePattern(grid, size, pattern, rng)
  const jitter = size <= 4 ? 1 : 2
  addCells(grid, size, jitter, rng)
  return grid
}

export function reseed(grid, size, count = 3, rng = Math.random) {
  const next = cloneGrid(grid)
  // Choose empty cells with the most live neighbours: these are the most
  // likely to give birth next generation, which feels good to new players.
  const candidates = []
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      if (isAlive(next, size, x, y)) continue
      const n = liveNeighbours(next, size, x, y)
      if (n > 0) candidates.push(y * size + x)
    }
  }
  const added = addCells(next, size, count, rng, candidates.length ? candidates : null)
  return { grid: next, added }
}

export function expandGrid(grid, oldSize, newSize) {
  const next = emptyGrid(newSize)
  const offset = Math.floor((newSize - oldSize) / 2)
  for (let y = 0; y < oldSize; y++) {
    for (let x = 0; x < oldSize; x++) {
      if (grid[y * oldSize + x]) next[(y + offset) * newSize + (x + offset)] = 1
    }
  }
  return next
}

export function bestSeedCells(grid, size, count = 3, rng = Math.random) {
  const options = []
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      if (isAlive(grid, size, x, y)) continue
      const n = liveNeighbours(grid, size, x, y)
      options.push({ i: y * size + x, score: n + rng() * 0.5 })
    }
  }
  options.sort((a, b) => b.score - a.score)
  return options.slice(0, count).map((o) => o.i)
}

export function randomAmbient(size, rng = Math.random) {
  const patterns = ['blinker', 'beacon', 'toad', 'glider']
  const grid = seedColony(size, patterns[Math.floor(rng() * patterns.length)], rng)
  removeCells(grid, size, Math.floor(rng() * 2), rng)
  return grid
}

/** Small deterministic RNG so simulations and tests are reproducible. */
export function mulberry32(seed) {
  let a = seed >>> 0
  return function random() {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function randomSeed() {
  return Math.floor(Math.random() * 0xffffffff)
}

export function pick(rng, list) {
  return list[Math.floor(rng() * list.length)]
}

export function shuffle(rng, list) {
  const copy = [...list]
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1))
    ;[copy[i], copy[j]] = [copy[j], copy[i]]
  }
  return copy
}

import {
  GAME,
  PLAYER_BLUEPRINTS,
  PROPERTY_TILES,
  LEVEL_SIZE,
  bookValue,
  levelRent,
  upgradeCost
} from './constants.js'
import { population, randomAmbient } from './life.js'
import { mulberry32, randomSeed } from './rng.js'

export const SAVE_VERSION = 1
export const SAVE_KEY = 'life-estate-save-v1'

export function createGame(options = {}) {
  const seed = options.seed ?? randomSeed()
  const rng = mulberry32(seed)
  const difficulty = options.difficulty || 'sharp'
  const humanToken = options.token || 'sprout'

  const players = PLAYER_BLUEPRINTS.map((bp) => ({
    ...bp,
    isAI: bp.id === 0 ? false : true,
    difficulty,
    cash: GAME.startCash,
    pos: 0,
    laps: 0,
    dormant: 0,
    bankrupt: false,
    stats: { rolls: 0, doubles: 0, propertiesBought: 0, rentPaid: 0, rentEarned: 0, cellsPlanted: 0 }
  }))

  // Allow the player to choose their token in future; keep colours unique now.
  const chosen = PLAYER_BLUEPRINTS.find((p) => p.token === humanToken)
  if (chosen && chosen.id !== 0) {
    const i = players.findIndex((p) => p.id === 0)
    const j = players.findIndex((p) => p.id === chosen.id)
    const a = players[i]
    const b = players[j]
    players[i] = { ...b, id: 0, isAI: false }
    players[j] = { ...a, id: chosen.id, isAI: true }
  }

  const colonies = {}
  for (const tile of PROPERTY_TILES) {
    const size = LEVEL_SIZE[0]
    const cells = randomAmbient(size, rng)
    colonies[tile.tile] = {
      tile: tile.tile,
      owner: null,
      level: 1,
      size,
      cells: Array.from(cells),
      population: population(cells),
      invested: 0,
      generations: 0
    }
  }

  return {
    version: SAVE_VERSION,
    seed,
    difficulty,
    turn: 0,
    round: 1,
    phase: 'playing',
    players,
    colonies,
    over: false,
    winner: null,
    pending: null,
    log: [],
    stats: { turns: 0, evolutions: 0, cards: 0, purchases: 0 },
    startedAt: Date.now()
  }
}

export function currentPlayer(state) {
  return state.players[state.turn]
}

export function livePlayers(state) {
  return state.players.filter((p) => !p.bankrupt)
}

export function ownedColonies(state, playerId) {
  return Object.values(state.colonies).filter((c) => c.owner === playerId)
}

export function colonyAt(state, tile) {
  return state.colonies[tile] || null
}

export function propertyValue(state, colony) {
  const tile = PROPERTY_TILES.find((t) => t.tile === colony.tile)
  return bookValue(tile, colony)
}

export function netWorth(state, player) {
  let total = player.cash
  for (const colony of ownedColonies(state, player.id)) {
    total += propertyValue(state, colony)
  }
  return Math.round(total)
}

export function rentFor(state, colony) {
  const tile = PROPERTY_TILES.find((t) => t.tile === colony.tile)
  return levelRent(tile, colony.level, colony.population)
}

export function districtCounts(state, playerId) {
  const counts = { meadow: 0, tide: 0, ember: 0, circuit: 0 }
  for (const colony of ownedColonies(state, playerId)) {
    const tile = PROPERTY_TILES.find((t) => t.tile === colony.tile)
    if (tile?.district) counts[tile.district]++
  }
  return counts
}

export function hasMonopoly(state, playerId, district) {
  return districtCounts(state, playerId)[district] === 4
}

export function upgradeCostFor(colony) {
  const tile = PROPERTY_TILES.find((t) => t.tile === colony.tile)
  return upgradeCost(tile, colony.level)
}

export function netWorthLeader(state) {
  return [...state.players].filter((p) => !p.bankrupt).sort((a, b) => netWorth(state, b) - netWorth(state, a))[0]
}

export function validateState(state) {
  if (!state || state.version !== SAVE_VERSION) return false
  if (!Array.isArray(state.players) || state.players.length !== 4) return false
  if (!state.colonies || typeof state.colonies !== 'object') return false
  for (const tile of PROPERTY_TILES) {
    const c = state.colonies[tile.tile]
    if (!c || !Array.isArray(c.cells)) return false
    if (c.size !== LEVEL_SIZE[c.level - 1]) return false
    if (c.cells.length !== c.size * c.size) return false
  }
  if (!Number.isFinite(state.turn) || state.turn < 0 || state.turn > 3) return false
  return true
}

export function loadGame(storage) {
  try {
    const raw = storage?.getItem(SAVE_KEY)
    if (!raw) return null
    const state = JSON.parse(raw)
    if (!validateState(state)) return null
    return state
  } catch {
    return null
  }
}

export function saveGame(storage, state) {
  try {
    storage?.setItem(SAVE_KEY, JSON.stringify(state))
    return true
  } catch {
    return false
  }
}

export function clearSave(storage) {
  try {
    storage?.removeItem(SAVE_KEY)
  } catch {
    /* storage may be unavailable */
  }
}

import {
  CARD_DECKS,
  DISTRICTS,
  GAME,
  LEVEL_SIZE,
  PROPERTY_TILES,
  PROPERTIES,
  TILE_COUNT,
  TILES,
  bookValue,
  levelRent,
  upgradeCost
} from './constants.js'
import {
  addCells,
  bestSeedCells,
  cloneGrid,
  emptyGrid,
  expandGrid,
  placePattern,
  population,
  randomAmbient,
  removeCells,
  stepLife
} from './life.js'
import { mulberry32 } from './rng.js'
import {
  colonyAt,
  currentPlayer,
  districtCounts,
  hasMonopoly,
  livePlayers,
  netWorth,
  ownedColonies,
  propertyValue,
  rentFor
} from './state.js'

const NOOP = async () => {}
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

export const instantPresenter = {
  delay: async () => {},
  roll: NOOP,
  move: NOOP,
  arrive: NOOP,
  salary: NOOP,
  pay: NOOP,
  gain: NOOP,
  notice: NOOP,
  evolve: NOOP,
  update: NOOP,
  waitForRoll: async () => {},
  chooseBuy: async () => true,
  manageProperty: NOOP,
  dormancyChoice: async () => true,
  showCard: NOOP,
  gameOver: NOOP,
  turn: NOOP,
  botThinking: NOOP
}

/**
 * The engine owns the rules. It is deliberately UI agnostic: the presenter
 * handles animation and human prompts, and the AI adapter makes decisions.
 */
export class GameEngine {
  constructor(state, options = {}) {
    this.state = state
    this.rng = options.rng || mulberry32(state.seed ?? Date.now())
    this.ui = { ...instantPresenter, ...(options.presenter || {}) }
    this.ai = options.ai || null
    this.onChange = options.onChange || null
    this.onLog = options.onLog || null
    this.running = false
    this.doublesStreak = 0
    this.extraTurn = false
    this.lastRoll = null
    this.seed = state.seed
  }

  emit() {
    this.ui.update?.(this.state)
    this.onChange?.(this.state)
  }

  log(text, kind = 'info') {
    this.state.log.push({ text, kind, round: this.state.round, at: Date.now() })
    if (this.state.log.length > 40) this.state.log.shift()
    this.ui.notice?.(text, kind)
    this.onLog?.(text, kind)
  }

  player(id) {
    return this.state.players.find((p) => p.id === id)
  }

  isHumanTurn() {
    const p = currentPlayer(this.state)
    return p && !p.isAI && !this.state.over
  }

  async start() {
    if (this.running || this.state.over) return
    this.running = true
    await this.ui.turn?.(currentPlayer(this.state))
    while (!this.state.over) {
      const p = currentPlayer(this.state)
      if (p.bankrupt) {
        this.advancePlayer()
        continue
      }
      if (p.dormant > 0) {
        p.dormant -= 1
        this.log(`${p.name} is dormant and misses a turn.`, 'muted')
        this.emit()
        await this.ui.delay?.(800)
        this.advancePlayer()
        continue
      }
      await this.takeTurn(p)
      if (this.state.over) break
      if (this.checkEnd()) break
      this.advancePlayer()
      await this.ui.turn?.(currentPlayer(this.state))
    }
    this.running = false
    await this.ui.gameOver?.(this.state)
  }

  advancePlayer() {
    if (this.extraTurn) {
      this.extraTurn = false
      this.state.stats.turns++
      this.emit()
      return
    }
    const prev = this.state.turn
    this.state.turn = (this.state.turn + 1) % this.state.players.length
    this.state.stats.turns++
    this.doublesStreak = 0
    if (prev === this.state.players.length - 1 && this.state.turn === 0) {
      this.state.round++
      // Evolution happens between rounds so every colony visibly breathes.
      this.pendingEvolution = true
    }
    this.emit()
  }

  async takeTurn(player) {
    this.state.stats.turns++
    this.ui.turn?.(player)
    if (this.pendingEvolution) {
      this.pendingEvolution = false
      await this.evolveBoard()
    }
    if (this.state.over) return

    if (player.isAI) {
      await this.ui.botThinking?.(player)
      await this.ui.delay?.(520)
    } else {
      await this.ui.waitForRoll?.(player)
    }

    const dice = this.rollDice()
    this.lastRoll = dice
    player.stats.rolls++
    this.state.stats.turns++
    this.log(`${player.name} rolled ${dice.a} + ${dice.b} = ${dice.total}.`, 'roll')
    await this.ui.roll?.(dice, player)
    this.emit()

    if (dice.a === dice.b) {
      this.doublesStreak++
      if (this.doublesStreak >= 3) {
        player.dormant = 1
        this.log(`${player.name} rolled three doubles and went dormant.`, 'bad')
        this.extraTurn = false
        this.emit()
        await this.ui.delay?.(700)
        return
      }
      this.extraTurn = true
    } else {
      this.doublesStreak = 0
      this.extraTurn = false
    }

    await this.movePlayer(player, dice.total)
    if (this.state.over) return
    await this.resolveLanding(player, player.pos, 0)
    if (this.state.over) return
    if (this.checkEnd()) return
    this.emit()
  }

  rollDice() {
    const a = 1 + Math.floor(this.rng() * 6)
    const b = 1 + Math.floor(this.rng() * 6)
    return { a, b, total: a + b, double: a === b }
  }

  async movePlayer(player, steps, options = {}) {
    let passed = false
    for (let i = 0; i < steps; i++) {
      const from = player.pos
      player.pos = (player.pos + 1) % TILE_COUNT
      if (player.pos === 0) {
        player.laps++
        passed = true
        if (options.salary !== false) await this.collectSalary(player)
      }
      await this.ui.move?.(player, from, player.pos, { passed })
    }
    await this.ui.arrive?.(player, player.pos)
    this.emit()
    return passed
  }

  async collectSalary(player) {
    player.cash += GAME.salary
    let yieldTotal = 0
    const yields = []
    for (const colony of ownedColonies(this.state, player.id)) {
      const income = colony.population * GAME.passIncomePerCell
      if (income > 0) {
        colony.cashEarned = (colony.cashEarned || 0) + income
        yieldTotal += income
        yields.push({ tile: colony.tile, income })
      }
    }
    player.cash += yieldTotal
    player.stats.rentEarned += yieldTotal
    this.log(
      yieldTotal > 0
        ? `${player.name} passed Genesis: +$${GAME.salary} salary, +$${yieldTotal} colony yield.`
        : `${player.name} passed Genesis: +$${GAME.salary} salary.`,
      'good'
    )
    await this.ui.salary?.(player, GAME.salary, yieldTotal, yields)
    this.emit()
  }

  async resolveLanding(player, tileIndex, depth = 0) {
    const tile = TILES[tileIndex]
    if (!tile) return

    if (tile.type === 'property') {
      const colony = colonyAt(this.state, tile.tile)
      if (!colony) return
      if (colony.owner == null) {
        const canAfford = player.cash >= tile.price
        let wants = false
        if (player.isAI) {
          wants = this.ai ? this.ai.shouldBuy(this, player, tile, colony) : canAfford
        } else {
          wants = await this.ui.chooseBuy?.(player, tile, colony, canAfford)
        }
        if (wants && canAfford) {
          this.buyProperty(player, colony, { quiet: false })
        } else if (!player.isAI) {
          this.log(`${player.name} passed on ${tile.name}.`, 'muted')
        }
        return
      }
      if (colony.owner === player.id) {
        this.log(`${player.name} stopped at their own ${tile.name}.`, 'muted')
        if (player.isAI && this.ai) {
          await this.ai.manage(this, player, colony)
        } else {
          await this.ui.manageProperty?.(player, tile, colony)
        }
        this.emit()
        return
      }
      const owner = this.player(colony.owner)
      const rent = rentFor(this.state, colony)
      this.log(`${player.name} pays ${owner.name} $${rent} at ${tile.name}.`, 'bad')
      player.stats.rentPaid += rent
      owner.stats.rentEarned += rent
      await this.charge(player, rent, owner, `rent at ${tile.name}`)
      return
    }

    if (tile.type === 'mutation' || tile.type === 'ecosystem') {
      const deckKey = tile.type
      const deck = CARD_DECKS[deckKey]
      const card = deck[Math.floor(this.rng() * deck.length)]
      this.state.stats.cards++
      if (player.isAI) {
        await this.ui.showCard?.(player, card, deckKey)
      } else {
        await this.ui.showCard?.(player, card, deckKey)
      }
      this.log(`${player.name} drew ${card.title}.`, 'card')
      await this.applyCard(player, card, depth)
      return
    }

    if (tile.type === 'tax') {
      const amount = Math.min(GAME.taxCap, Math.round(player.cash * GAME.taxRate))
      this.log(`${player.name} pays $${amount} Bloom Tax.`, 'bad')
      await this.charge(player, amount, null, 'Bloom Tax')
      return
    }

    if (tile.type === 'dormancy') {
      let pay = false
      if (player.isAI) {
        pay = this.ai ? this.ai.shouldPayDormancy(this, player) : player.cash > 500
      } else {
        pay = await this.ui.dormancyChoice?.(player, GAME.dormancyFee)
      }
      if (pay && player.cash >= GAME.dormancyFee) {
        await this.charge(player, GAME.dormancyFee, null, 'revival')
        this.log(`${player.name} pays to wake up immediately.`, 'info')
      } else {
        player.dormant = 1
        this.log(`${player.name} falls dormant and will skip a turn.`, 'bad')
      }
      this.emit()
      return
    }

    if (tile.type === 'sanctuary') {
      player.cash += GAME.sanctuaryBonus
      let cells = 0
      for (const colony of ownedColonies(this.state, player.id)) {
        cells += addCells(Uint8Array.from(colony.cells), colony.size, 1, this.rng) // count only
        const grid = Uint8Array.from(colony.cells)
        if (addCells(grid, colony.size, 1, this.rng)) {
          colony.cells = Array.from(grid)
          colony.population = population(grid)
        }
      }
      this.log(`${player.name} rests at Sanctuary: +$${GAME.sanctuaryBonus} and fresh spores.`, 'good')
      await this.ui.gain?.(player, GAME.sanctuaryBonus, 'Sanctuary')
      this.emit()
      return
    }

    if (tile.type === 'geneLab') {
      const owned = ownedColonies(this.state, player.id).filter((c) => c.level < GAME.maxLevel)
      if (owned.length) {
        owned.sort((a, b) => a.level - b.level || a.population - b.population)
        this.freeUpgrade(player, owned[0])
        this.log(`Gene Lab upgrades ${PROPERTIES.get(owned[0].tile).name} for free.`, 'good')
      } else {
        player.cash += GAME.geneLabBonus
        this.log(`Gene Lab pays ${player.name} $${GAME.geneLabBonus}.`, 'good')
        await this.ui.gain?.(player, GAME.geneLabBonus, 'Gene Lab')
      }
      this.emit()
      return
    }

    if (tile.type === 'start') {
      player.cash += 80
      this.log(`${player.name} lands on Genesis: +$80.`, 'good')
      await this.ui.gain?.(player, 80, 'Genesis')
      this.emit()
    }
  }

  buyProperty(player, colony, options = {}) {
    const tile = PROPERTIES.get(colony.tile)
    if (!tile || colony.owner != null) return false
    if (player.cash < tile.price) return false
    player.cash -= tile.price
    colony.owner = player.id
    colony.invested = 0
    colony.acquiredRound = this.state.round
    const grid = Uint8Array.from(colony.cells)
    placePattern(grid, colony.size, tile.pattern, this.rng)
    addCells(grid, colony.size, 1, this.rng)
    colony.cells = Array.from(grid)
    colony.population = population(grid)
    player.stats.propertiesBought++
    this.state.stats.purchases++
    if (!options.quiet) this.log(`${player.name} bought ${tile.name} for $${tile.price}.`, 'good')
    this.emit()
    return true
  }

  upgradeProperty(colony, free = false) {
    const player = this.player(colony.owner)
    if (!player) return false
    if (colony.level >= GAME.maxLevel) return false
    const tile = PROPERTIES.get(colony.tile)
    const cost = upgradeCost(tile, colony.level)
    if (!free && player.cash < cost) return false
    if (!free) player.cash -= cost
    colony.invested += free ? 0 : cost
    const oldSize = colony.size
    colony.level++
    colony.size = LEVEL_SIZE[colony.level - 1]
    const grid = expandGrid(Uint8Array.from(colony.cells), oldSize, colony.size)
    addCells(grid, colony.size, 2, this.rng)
    colony.cells = Array.from(grid)
    colony.population = population(grid)
    if (!free) this.log(`${player.name} upgraded ${tile.name} to ${colony.level === 2 ? 'Grove' : 'Biome'} for $${cost}.`, 'good')
    this.emit()
    return true
  }

  freeUpgrade(player, colony) {
    const p = this.player(player.id)
    if (!p || colony.owner !== p.id) return false
    return this.upgradeProperty(colony, true)
  }

  seedColony(colony, indices) {
    if (!colony || !Array.isArray(indices) || !indices.length) return 0
    const grid = Uint8Array.from(colony.cells)
    let added = 0
    for (const i of indices.slice(0, 3)) {
      if (i < 0 || i >= grid.length) continue
      if (grid[i]) continue
      grid[i] = 1
      added++
    }
    if (added) {
      const owner = this.player(colony.owner)
      if (owner) owner.stats.cellsPlanted += added
      colony.cells = Array.from(grid)
      colony.population = population(grid)
      this.log(`${owner ? owner.name : 'A colony'} planted ${added} cell${added === 1 ? '' : 's'} in ${PROPERTIES.get(colony.tile).name}.`, 'good')
      this.emit()
    }
    return added
  }

  harvestColony(player, colony) {
    if (!player || colony.owner !== player.id) return 0
    const gain = Math.max(12, colony.population * GAME.harvestMultiplier)
    player.cash += gain
    const grid = emptyGrid(colony.size)
    addCells(grid, colony.size, 2, this.rng)
    colony.cells = Array.from(grid)
    colony.population = population(grid)
    player.stats.cellsPlanted += 0
    this.log(`${player.name} harvests ${PROPERTIES.get(colony.tile).name} for $${gain}.`, 'info')
    this.emit()
    return gain
  }

  async charge(player, amount, creditor = null, reason = '') {
    if (amount <= 0) return true
    if (player.cash < amount) {
      const needed = amount - player.cash
      await this.liquidate(player, needed)
    }
    const paid = Math.min(player.cash, Math.max(0, amount))
    player.cash -= paid
    if (creditor && creditor.id !== player.id) creditor.cash += paid
    await this.ui.pay?.(player, creditor, paid, reason)
    this.emit()
    if (paid < amount) {
      this.bankrupt(player, creditor)
      return false
    }
    return true
  }

  async liquidate(player, needed) {
    const owned = ownedColonies(this.state, player.id).sort(
      (a, b) => propertyValue(this.state, a) - propertyValue(this.state, b)
    )
    for (const colony of owned) {
      if (player.cash >= needed + 0) break
      const tile = PROPERTIES.get(colony.tile)
      const sale = Math.round(bookValue(tile, colony) * GAME.sellRatio)
      player.cash += sale
      this.releaseColony(colony)
      this.log(`${player.name} sold ${tile.name} to the bank for $${sale}.`, 'bad')
      await this.ui.notice?.(`${tile.name} sold for $${sale}`, 'bad')
    }
    this.emit()
  }

  releaseColony(colony) {
    const tile = PROPERTIES.get(colony.tile)
    colony.owner = null
    colony.level = 1
    colony.size = LEVEL_SIZE[0]
    colony.invested = 0
    colony.cells = Array.from(randomAmbient(colony.size, this.rng))
    colony.population = population(colony.cells)
    return tile
  }

  bankrupt(player, creditor = null) {
    if (player.bankrupt) return
    player.cash = 0
    player.bankrupt = true
    player.pos = 0
    for (const colony of ownedColonies(this.state, player.id)) this.releaseColony(colony)
    this.log(`${player.name} has gone bankrupt${creditor ? ` to ${creditor.name}` : ''}.`, 'bad')
    this.emit()
    if (!player.isAI) this.checkEnd()
  }

  async applyCard(player, card, depth = 0) {
    const effect = card.effect
    if (effect.type === 'gain') {
      player.cash += effect.amount
      await this.ui.gain?.(player, effect.amount, card.title)
    } else if (effect.type === 'lose') {
      await this.charge(player, effect.amount, null, card.title)
    } else if (effect.type === 'seedAll') {
      for (const colony of ownedColonies(this.state, player.id)) this.seedColony(colony, this.randomCells(colony, effect.count))
    } else if (effect.type === 'gainSeedAll') {
      player.cash += effect.amount
      await this.ui.gain?.(player, effect.amount, card.title)
      for (const colony of ownedColonies(this.state, player.id)) this.seedColony(colony, this.randomCells(colony, effect.count))
    } else if (effect.type === 'payEach') {
      for (const other of livePlayers(this.state)) {
        if (other.id === player.id) continue
        await this.charge(player, effect.amount, other, card.title)
      }
    } else if (effect.type === 'collectEach') {
      for (const other of livePlayers(this.state)) {
        if (other.id === player.id) continue
        await this.charge(other, effect.amount, player, card.title)
      }
    } else if (effect.type === 'collectPerProperty') {
      const amount = ownedColonies(this.state, player.id).length * effect.amount
      player.cash += amount
      await this.ui.gain?.(player, amount, card.title)
    } else if (effect.type === 'payPerProperty') {
      await this.charge(player, ownedColonies(this.state, player.id).length * effect.amount, null, card.title)
    } else if (effect.type === 'collectPerCell') {
      let cells = 0
      for (const colony of ownedColonies(this.state, player.id)) cells += colony.population
      const amount = cells * effect.amount
      player.cash += amount
      await this.ui.gain?.(player, amount, card.title)
    } else if (effect.type === 'collectPerLevel') {
      let levels = 0
      for (const colony of ownedColonies(this.state, player.id)) levels += colony.level
      const amount = levels * effect.amount
      player.cash += amount
      await this.ui.gain?.(player, amount, card.title)
    } else if (effect.type === 'payPerLevel') {
      let levels = 0
      for (const colony of ownedColonies(this.state, player.id)) levels += colony.level
      await this.charge(player, levels * effect.amount, null, card.title)
    } else if (effect.type === 'killAll') {
      for (const colony of Object.values(this.state.colonies)) {
        const grid = Uint8Array.from(colony.cells)
        removeCells(grid, colony.size, effect.count, this.rng)
        colony.cells = Array.from(grid)
        colony.population = population(grid)
      }
      this.log('A dry spell thins every colony on the board.', 'bad')
    } else if (effect.type === 'patternAll') {
      for (const colony of ownedColonies(this.state, player.id)) {
        const grid = Uint8Array.from(colony.cells)
        placePattern(grid, colony.size, effect.pattern, this.rng)
        colony.cells = Array.from(grid)
        colony.population = population(grid)
      }
    } else if (effect.type === 'move' && depth < 2) {
      this.log(`${player.name} migrates ${effect.steps} tiles.`, 'info')
      const passed = await this.movePlayer(player, effect.steps, { salary: effect.salary })
      if (passed) player.laps--
      await this.resolveLanding(player, player.pos, depth + 1)
    } else if (effect.type === 'evolveGain') {
      let cells = 0
      for (const colony of ownedColonies(this.state, player.id)) {
        for (let g = 0; g < effect.generations; g++) {
          const result = stepLife(Uint8Array.from(colony.cells), colony.size, this.rng)
          colony.cells = Array.from(result.grid)
          colony.population = result.population
          colony.generations += 1
        }
        cells += colony.population
      }
      const amount = cells * effect.perCell
      player.cash += amount
      this.log(`Revival stirs ${cells} cells: +$${amount}.`, 'good')
      await this.ui.gain?.(player, amount, card.title)
    } else if (effect.type === 'gainSeed') {
      player.cash += effect.amount
      await this.ui.gain?.(player, effect.amount, card.title)
      const owned = ownedColonies(this.state, player.id)
      if (owned.length) this.seedColony(owned[0], this.randomCells(owned[0], effect.count))
    } else if (effect.type === 'districtGrant') {
      const counts = districtCounts(this.state, player.id)
      const best = Math.max(...Object.values(counts))
      const amount = best >= 2 ? effect.amount : effect.fallback
      player.cash += amount
      this.log(`Civic Grant pays ${player.name} $${amount}.`, 'good')
      await this.ui.gain?.(player, amount, card.title)
    } else if (effect.type === 'freeUpgrade') {
      const owned = ownedColonies(this.state, player.id)
        .filter((c) => c.level < GAME.maxLevel)
        .sort((a, b) => a.level - b.level || a.population - b.population)
      if (owned.length) {
        this.freeUpgrade(player, owned[0])
        this.log(`Research upgrades ${PROPERTIES.get(owned[0].tile).name}.`, 'good')
      } else {
        player.cash += 120
        await this.ui.gain?.(player, 120, card.title)
      }
    }
    this.emit()
  }

  randomCells(colony, count) {
    const grid = Uint8Array.from(colony.cells)
    const picks = bestSeedCells(grid, colony.size, count, this.rng)
    return picks
  }

  async evolveBoard() {
    const reports = []
    for (const colony of Object.values(this.state.colonies)) {
      const before = Uint8Array.from(colony.cells)
      const result = stepLife(before, colony.size, this.rng)
      const tile = PROPERTIES.get(colony.tile)
      colony.cells = Array.from(result.grid)
      colony.population = result.population
      colony.generations += 1
      let income = 0
      if (colony.owner != null) {
        income = colony.population * (colony.level >= 3 ? 2 : 1)
        const owner = this.player(colony.owner)
        if (owner) {
          owner.cash += income
          owner.stats.rentEarned += income
        }
      }
      reports.push({
        tile: colony.tile,
        name: tile.name,
        before,
        after: result.grid,
        born: result.born,
        died: result.died,
        population: result.population,
        income,
        owner: colony.owner
      })
    }
    this.state.stats.evolutions++
    await this.ui.evolve?.(reports, this.state)
    this.log(`Generation ${this.state.round}: every colony evolved.`, 'life')
    this.emit()
  }

  checkEnd() {
    if (this.state.over) return true
    const alive = livePlayers(this.state)
    const target = alive.find((p) => netWorth(this.state, p) >= GAME.victoryNetWorth)
    if (target) {
      this.endGame(target, `${target.name} reached $${GAME.victoryNetWorth.toLocaleString()} net worth.`)
      return true
    }
    if (alive.length <= 1) {
      this.endGame(alive[0] || null, alive[0] ? 'Every rival has gone bankrupt.' : 'The board has emptied.')
      return true
    }
    const human = this.state.players.find((p) => !p.isAI)
    if (human && human.bankrupt) {
      const leader = [...alive].sort((a, b) => netWorth(this.state, b) - netWorth(this.state, a))[0]
      this.endGame(leader || null, 'You have gone bankrupt.')
      return true
    }
    return false
  }

  endGame(winner, reason) {
    this.state.over = true
    this.state.phase = 'over'
    this.state.winner = winner ? winner.id : null
    this.state.endReason = reason
    if (winner) winner.isWinner = true
    this.log(reason, 'end')
    this.emit()
  }

  // ---- public helpers used by UI modals -----------------------------------

  canBuy(player, tile, colony) {
    return colony.owner == null && player.cash >= tile.price && currentPlayer(this.state).id === player.id
  }

  canUpgrade(player, colony) {
    if (colony.owner !== player.id || colony.level >= GAME.maxLevel) return false
    const cost = upgradeCost(PROPERTIES.get(colony.tile), colony.level)
    return player.cash >= cost && currentPlayer(this.state).id === player.id
  }

  upgradePrice(colony) {
    return upgradeCost(PROPERTIES.get(colony.tile), colony.level)
  }

  rentAt(colony) {
    return levelRent(PROPERTIES.get(colony.tile), colony.level, colony.population)
  }

  netWorth(player) {
    return netWorth(this.state, player)
  }

  districtCounts(player) {
    return districtCounts(this.state, player.id)
  }

  hasMonopoly(player, district) {
    return hasMonopoly(this.state, player.id, district)
  }
}

export { NOOP, wait }

import { GAME, PROPERTIES } from './constants.js'
import { bestSeedCells, emptyGrid, isAlive, liveNeighbours, population } from './life.js'

/**
 * A compact heuristic opponent. It values completing a colour set, keeps a
 * cash buffer, upgrades developed colonies and reseeds empty ones.
 */
export class AIPlayer {
  constructor(difficulty = 'sharp') {
    this.difficulty = difficulty
    this.reserve = GAME.aiReserve[difficulty] ?? GAME.aiReserve.sharp
  }

  shouldBuy(engine, player, tile, colony) {
    const price = tile.price
    if (player.cash < price) return false
    const counts = engine.districtCounts(player)
    const completes = counts[tile.district] >= 2
    const after = player.cash - price
    if (after < 0) return false
    if (!completes && after < this.reserve) return false
    if (completes) return true

    if (this.difficulty === 'cozy') {
      if (player.cash - price < this.reserve) return false
      return engine.rng() < 0.7
    }
    if (this.difficulty === 'sharp') {
      if (after < this.reserve * 0.6) return engine.rng() < 0.5
      return true
    }
    return true
  }

  shouldPayDormancy(engine, player) {
    return player.cash > Math.max(220, this.reserve * 0.7)
  }

  async manage(engine, player, colony) {
    const tile = PROPERTIES.get(colony.tile)
    const counts = engine.districtCounts(player)
    const monopoly = counts[tile.district] >= 4
    const reserve = this.reserve * (this.difficulty === 'ruthless' ? 0.45 : 0.8)
    let actions = 0

    const tryUpgrade = () => {
      if (actions >= 2) return false
      if (!engine.canUpgrade(player, colony)) return false
      const cost = engine.upgradePrice(colony)
      const should =
        player.cash - cost > reserve ||
        (monopoly && colony.level < 3) ||
        (colony.level === 1 && player.cash - cost > reserve * 0.5)
      if (!should) return false
      engine.upgradeProperty(colony, false)
      actions++
      return true
    }

    if (colony.level < GAME.maxLevel) {
      if (colony.level === 1 || monopoly) tryUpgrade()
    }

    if (actions === 0 || colony.population < 8) {
      const cells = this.chooseSeeds(engine, colony, this.difficulty === 'ruthless' ? 3 : 2)
      if (cells.length) {
        engine.seedColony(colony, cells)
        actions++
      }
    }

    if (
      actions === 0 &&
      colony.population >= 8 &&
      player.cash < this.reserve * 0.8 &&
      this.difficulty !== 'cozy'
    ) {
      engine.harvestColony(player, colony)
      actions++
    }

    return actions
  }

  chooseSeeds(engine, colony, count) {
    if (colony.population === 0) {
      return bestSeedCells(emptyGrid(colony.size), colony.size, count, engine.rng)
    }
    // Prefer births with 2 or 3 neighbours; avoid overcrowded cells.
    const size = colony.size
    const grid = Uint8Array.from(colony.cells)
    const options = []
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        if (isAlive(grid, size, x, y)) continue
        const n = liveNeighbours(grid, size, x, y)
        if (n === 2 || n === 3) options.push({ i: y * size + x, n })
      }
    }
    if (!options.length) return bestSeedCells(grid, size, count, engine.rng)
    options.sort((a, b) => b.n - a.n)
    return options.slice(0, count).map((o) => o.i)
  }

  choosePattern(engine, colony, pattern) {
    const cells = []
    const size = colony.size
    const grid = Uint8Array.from(colony.cells)
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        if (!isAlive(grid, size, x, y)) cells.push(y * size + x)
      }
    }
    return cells.slice(0, 3)
  }
}

export function aiFor(difficulty) {
  return new AIPlayer(difficulty)
}

import test from 'node:test'
import assert from 'node:assert/strict'
import {
  emptyGrid,
  population,
  placePattern,
  stepLife,
  expandGrid,
  bestSeedCells,
  seedColony
} from '../src/game/life.js'
import { mulberry32 } from '../src/game/rng.js'

test('blinker oscillates with period 2', () => {
  const size = 6
  let grid = emptyGrid(size)
  placePattern(grid, size, 'blinker', mulberry32(1), 1, 1)
  assert.equal(population(grid), 3)
  const a = stepLife(grid, size, mulberry32(2), { immigration: false })
  assert.equal(a.population, 3)
  const b = stepLife(a.grid, size, mulberry32(3), { immigration: false })
  assert.deepEqual(Array.from(b.grid), Array.from(grid))
})

test('block is a still life', () => {
  const size = 6
  let grid = emptyGrid(size)
  placePattern(grid, size, 'block', mulberry32(1), 1, 1)
  const next = stepLife(grid, size, mulberry32(2), { immigration: false })
  assert.deepEqual(Array.from(next.grid), Array.from(grid))
  assert.equal(next.population, 4)
})

test('torus wraps gliders and preserves population', () => {
  const size = 6
  let grid = emptyGrid(size)
  placePattern(grid, size, 'glider', mulberry32(1), 1, 1)
  const initial = population(grid)
  let current = grid
  for (let i = 0; i < 4; i++) {
    current = stepLife(current, size, mulberry32(i), { immigration: false }).grid
  }
  assert.equal(population(current), initial)
})

test('immigration rescues a dead colony', () => {
  const size = 4
  const dead = emptyGrid(size)
  const next = stepLife(dead, size, mulberry32(9))
  assert.ok(next.population >= 1)
})

test('expandGrid centers the old colony', () => {
  const size = 4
  const grid = emptyGrid(size)
  grid[0] = 1
  const bigger = expandGrid(grid, size, 6)
  assert.equal(bigger.length, 36)
  assert.equal(bigger[1 * 6 + 1], 1)
  assert.equal(population(bigger), 1)
})

test('seed selection favours fertile empty cells', () => {
  const size = 6
  const grid = emptyGrid(size)
  placePattern(grid, size, 'blinker', mulberry32(1), 2, 2)
  const picks = bestSeedCells(grid, size, 2, mulberry32(4))
  assert.equal(picks.length, 2)
  for (const i of picks) assert.equal(grid[i], 0)
})

test('seeded colonies are alive', () => {
  const grid = seedColony(5, 'rpent', mulberry32(7))
  assert.ok(population(grid) >= 5)
})

import test from 'node:test'
import assert from 'node:assert/strict'
import { createGame, netWorth, ownedColonies, validateState } from '../src/game/state.js'
import { GameEngine, instantPresenter } from '../src/game/engine.js'
import { AIPlayer } from '../src/game/ai.js'
import { mulberry32 } from '../src/game/rng.js'
import { GAME, PROPERTIES } from '../src/game/constants.js'
import { population } from '../src/game/life.js'

function engineFor(seed = 42, presenter = {}) {
  const state = createGame({ seed })
  const ai = new AIPlayer('sharp')
  const engine = new GameEngine(state, {
    rng: mulberry32(seed + 1),
    presenter: { ...instantPresenter, ...presenter },
    ai
  })
  return { state, engine, ai }
}

test('new game is valid and fully populated', () => {
  const state = createGame({ seed: 7 })
  assert.equal(state.players.length, 4)
  assert.equal(Object.keys(state.colonies).length, 16)
  assert.equal(validateState(state), true)
  for (const colony of Object.values(state.colonies)) {
    assert.ok(colony.population > 0)
    assert.equal(colony.cells.length, colony.size * colony.size)
  }
})

test('buying a property deducts cash and transfers ownership', () => {
  const { state, engine } = engineFor()
  const player = state.players[0]
  const colony = state.colonies[1]
  const tile = PROPERTIES.get(1)
  const before = player.cash
  const ok = engine.buyProperty(player, colony)
  assert.equal(ok, true)
  assert.equal(player.cash, before - tile.price)
  assert.equal(colony.owner, player.id)
  assert.ok(colony.population > 0)
})

test('rent is higher for developed colonies', () => {
  const { state, engine } = engineFor()
  const player = state.players[0]
  const colony = state.colonies[1]
  engine.buyProperty(player, colony)
  const rent1 = engine.rentAt(colony)
  player.cash += 5000
  engine.upgradeProperty(colony, false)
  const rent2 = engine.rentAt(colony)
  assert.ok(rent2 > rent1)
  assert.equal(colony.level, 2)
  assert.equal(colony.size, 5)
})

test('bankrupt player releases colonies', () => {
  const { state, engine } = engineFor()
  const player = state.players[0]
  const colony = state.colonies[1]
  engine.buyProperty(player, colony)
  player.cash = 0
  engine.bankrupt(player)
  assert.equal(player.bankrupt, true)
  assert.equal(colony.owner, null)
  assert.equal(engine.netWorth(player), 0)
})

test('full AI game finishes', async () => {
  const { state, engine } = engineFor(11)
  for (const p of state.players) p.isAI = true
  let turns = 0
  const guard = setInterval(() => {}, 1000)
  try {
    const original = engine.takeTurn.bind(engine)
    engine.takeTurn = async (player) => {
      turns++
      return original(player)
    }
    await engine.start()
    assert.equal(state.over, true)
    assert.ok(turns > 0)
    assert.ok(state.winner != null || state.players.every((p) => p.bankrupt))
    const winner = state.players[state.winner]
    if (winner) assert.ok(netWorth(state, winner) > 0)
  } finally {
    clearInterval(guard)
  }
})

test('net worth includes cash and book value', () => {
  const { state, engine } = engineFor()
  const player = state.players[0]
  const start = netWorth(state, player)
  assert.equal(start, player.cash)
  engine.buyProperty(player, state.colonies[2])
  const after = netWorth(state, player)
  assert.ok(after >= player.cash)
  assert.equal(ownedColonies(state, player.id).length, 1)
})

/**
 * Headless balance lab: npm run sim -- [games] [difficulty]
 * Every player is AI, so we can measure game length and the win spread.
 */
import { createGame, netWorth } from '../src/game/state.js'
import { GameEngine, instantPresenter } from '../src/game/engine.js'
import { AIPlayer } from '../src/game/ai.js'
import { mulberry32 } from '../src/game/rng.js'
import { GAME } from '../src/game/constants.js'

const games = Number(process.argv[2] || 200)
const difficulty = process.argv[3] || 'sharp'
const results = []

for (let seed = 1; seed <= games; seed++) {
  const state = createGame({ seed, difficulty })
  for (const p of state.players) {
    p.isAI = true
    p.difficulty = difficulty
  }
  const ai = new AIPlayer(difficulty)
  const engine = new GameEngine(state, {
    rng: mulberry32(seed * 7919),
    presenter: instantPresenter,
    ai
  })
  let turns = 0
  const original = engine.takeTurn.bind(engine)
  engine.takeTurn = async (player) => {
    turns++
    if (turns > 600) {
      state.over = true
      state.endReason = 'turn cap'
      return
    }
    return original(player)
  }
  await engine.start()
  const winner = state.players.find((p) => p.id === state.winner)
  results.push({
    seed,
    turns,
    rounds: state.round,
    winner: winner?.name ?? 'none',
    reason: state.endReason ?? '',
    winnerNet: winner ? netWorth(state, winner) : 0,
    bankrupt: state.players.filter((p) => p.bankrupt).length,
    properties: state.players.map((p) => Object.values(state.colonies).filter((c) => c.owner === p.id).length),
    cash: state.players.map((p) => p.cash),
    over: state.over
  })
}

const avg = (xs) => xs.reduce((a, b) => a + b, 0) / Math.max(1, xs.length)
const pct = (n) => ((n / results.length) * 100).toFixed(1) + '%'
const wins = {}
for (const r of results) wins[r.winner] = (wins[r.winner] || 0) + 1
const capped = results.filter((r) => r.turns > 600).length
const targetWins = results.filter((r) => r.reason.includes('net worth')).length
const bankruptcyWins = results.filter((r) => r.reason.includes('bankrupt')).length

console.log(`Games: ${results.length}  difficulty: ${difficulty}`)
console.log(`Turns   avg ${avg(results.map((r) => r.turns)).toFixed(1)}  min ${Math.min(...results.map((r) => r.turns))}  max ${Math.max(...results.map((r) => r.turns))}`)
console.log(`Rounds  avg ${avg(results.map((r) => r.rounds)).toFixed(1)}  max ${Math.max(...results.map((r) => r.rounds))}`)
console.log(`Winner  ${JSON.stringify(wins)}`)
console.log(`End     target ${pct(targetWins)}  bankruptcy ${pct(bankruptcyWins)}  cap ${capped}`)
console.log(`NetWorth avg $${avg(results.map((r) => r.winnerNet)).toFixed(0)}  target $${GAME.victoryNetWorth}`)
console.log(`Bankruptcies avg ${avg(results.map((r) => r.bankrupt)).toFixed(2)}`)
console.log(`Owner spread avg ${JSON.stringify(results[0].properties.map((_, i) => avg(results.map((r) => r.properties[i])).toFixed(1)))}`)

