import * as THREE from 'three'

const FONT = 'Outfit, system-ui, sans-serif'
const SERIF = 'Fraunces, Georgia, serif'

function canvasTexture(width, height, draw, options = {}) {
  const canvas = document.createElement('canvas')
  canvas.width = width
  canvas.height = height
  const ctx = canvas.getContext('2d')
  draw(ctx, width, height)
  const texture = new THREE.CanvasTexture(canvas)
  texture.colorSpace = THREE.SRGBColorSpace
  texture.anisotropy = options.anisotropy || 4
  texture.needsUpdate = true
  return texture
}

function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2)
  ctx.beginPath()
  ctx.moveTo(x + radius, y)
  ctx.arcTo(x + w, y, x + w, y + h, radius)
  ctx.arcTo(x + w, y + h, x, y + h, radius)
  ctx.arcTo(x, y + h, x, y, radius)
  ctx.arcTo(x, y, x + w, y, radius)
  ctx.closePath()
}

function hexToRgba(hex, alpha) {
  const clean = hex.replace('#', '')
  const value = parseInt(clean.length === 3 ? clean.split('').map((c) => c + c).join('') : clean, 16)
  const r = (value >> 16) & 255
  const g = (value >> 8) & 255
  const b = value & 255
  return `rgba(${r}, ${g}, ${b}, ${alpha})`
}

export function labelTexture({ title, subtitle, accent = '#A8E063', icon = '', owned = false }) {
  return canvasTexture(640, 208, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h)

    // soft plate
    ctx.save()
    ctx.shadowColor = 'rgba(0,0,0,0.5)'
    ctx.shadowBlur = 22
    ctx.shadowOffsetY = 8
    ctx.fillStyle = 'rgba(7,25,26,0.74)'
    roundRect(ctx, 14, 24, w - 28, h - 48, 34)
    ctx.fill()
    ctx.restore()

    ctx.strokeStyle = hexToRgba(accent, 0.5)
    ctx.lineWidth = 3
    roundRect(ctx, 14, 24, w - 28, h - 48, 34)
    ctx.stroke()

    if (icon) {
      ctx.fillStyle = hexToRgba(accent, 0.2)
      ctx.beginPath()
      ctx.arc(86, h / 2, 44, 0, Math.PI * 2)
      ctx.fill()
      ctx.strokeStyle = hexToRgba(accent, 0.8)
      ctx.lineWidth = 3
      ctx.stroke()
      ctx.font = `600 48px ${SERIF}`
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      ctx.fillStyle = accent
      ctx.fillText(icon, 86, h / 2 + 2)
    }

    const left = icon ? 150 : 48
    ctx.textAlign = 'left'
    ctx.textBaseline = 'middle'
    ctx.font = `700 55px ${FONT}`
    ctx.fillStyle = '#FFF8E7'
    ctx.fillText(title.toUpperCase(), left, 82)

    ctx.font = `500 35px ${FONT}`
    ctx.fillStyle = owned ? accent : hexToRgba(accent, 0.95)
    ctx.fillText(subtitle.toUpperCase(), left, 142)

    if (owned) {
      ctx.beginPath()
      ctx.arc(w - 58, h / 2, 15, 0, Math.PI * 2)
      ctx.fillStyle = accent
      ctx.fill()
    }
  })
}

export function pipTexture(value, color = '#F7EEDC', pip = '#21312D') {
  return canvasTexture(256, 256, (ctx, w, h) => {
    ctx.fillStyle = color
    roundRect(ctx, 6, 6, w - 12, h - 12, 44)
    ctx.fill()
    ctx.strokeStyle = 'rgba(0,0,0,0.18)'
    ctx.lineWidth = 5
    roundRect(ctx, 10, 10, w - 20, h - 20, 40)
    ctx.stroke()

    const positions = {
      1: [[0.5, 0.5]],
      2: [[0.28, 0.28], [0.72, 0.72]],
      3: [[0.25, 0.25], [0.5, 0.5], [0.75, 0.75]],
      4: [[0.28, 0.28], [0.72, 0.28], [0.28, 0.72], [0.72, 0.72]],
      5: [[0.26, 0.26], [0.74, 0.26], [0.5, 0.5], [0.26, 0.74], [0.74, 0.74]],
      6: [[0.27, 0.24], [0.73, 0.24], [0.27, 0.5], [0.73, 0.5], [0.27, 0.76], [0.73, 0.76]]
    }
    ctx.fillStyle = pip
    for (const [x, y] of positions[value] || positions[1]) {
      ctx.beginPath()
      ctx.arc(x * w, y * h, 20, 0, Math.PI * 2)
      ctx.fill()
      ctx.fillStyle = 'rgba(255,255,255,0.26)'
      ctx.beginPath()
      ctx.arc(x * w - 5, y * h - 6, 6, 0, Math.PI * 2)
      ctx.fill()
      ctx.fillStyle = pip
    }
  })
}

export function glowTexture(color = '#C8FF8A') {
  return canvasTexture(256, 256, (ctx, w, h) => {
    const gradient = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2)
    gradient.addColorStop(0, hexToRgba(color, 0.95))
    gradient.addColorStop(0.25, hexToRgba(color, 0.5))
    gradient.addColorStop(0.6, hexToRgba(color, 0.12))
    gradient.addColorStop(1, hexToRgba(color, 0))
    ctx.fillStyle = gradient
    ctx.fillRect(0, 0, w, h)
  })
}

export function cloudTexture() {
  return canvasTexture(512, 256, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h)
    const blobs = [
      [140, 150, 90],
      [220, 120, 110],
      [320, 145, 85],
      [380, 165, 65],
      [80, 175, 55]
    ]
    for (const [x, y, r] of blobs) {
      const g = ctx.createRadialGradient(x, y, 0, x, y, r)
      g.addColorStop(0, 'rgba(255,245,225,0.85)')
      g.addColorStop(0.5, 'rgba(255,240,220,0.4)')
      g.addColorStop(1, 'rgba(255,240,220,0)')
      ctx.fillStyle = g
      ctx.beginPath()
      ctx.arc(x, y, r, 0, Math.PI * 2)
      ctx.fill()
    }
  })
}

export function grassTexture() {
  return canvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#477a4d'
    ctx.fillRect(0, 0, w, h)
    for (let i = 0; i < 2400; i++) {
      const x = Math.random() * w
      const y = Math.random() * h
      const shade = Math.random()
      ctx.fillStyle = shade > 0.6 ? 'rgba(190,230,150,0.13)' : 'rgba(12,60,38,0.12)'
      ctx.fillRect(x, y, 2 + Math.random() * 3, 2 + Math.random() * 3)
    }
  })
}

export function boardTexture() {
  return canvasTexture(1024, 1024, (ctx, w, h) => {
    ctx.fillStyle = '#194842'
    ctx.fillRect(0, 0, w, h)
    for (let i = 0; i < 9000; i++) {
      const x = Math.random() * w
      const y = Math.random() * h
      const a = Math.random() * 0.05
      ctx.fillStyle = Math.random() > 0.5 ? `rgba(255,255,255,${a})` : `rgba(0,0,0,${a})`
      ctx.fillRect(x, y, 1 + Math.random() * 3, 1 + Math.random() * 3)
    }
  })
}

export function logoTexture() {
  return canvasTexture(1200, 360, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h)
    ctx.textAlign = 'left'
    ctx.textBaseline = 'middle'
    ctx.font = `700 230px ${SERIF}`
    ctx.fillStyle = '#F5EEDC'
    ctx.fillText('Life', 40, h / 2 - 8)
    ctx.font = `600 150px ${FONT}`
    const lifeWidth = ctx.measureText('Life ').width
    ctx.fillStyle = '#A8E063'
    ctx.fillText('ESTATE', 50 + lifeWidth, h / 2 + 12)
  })
}

/**
 * Tiny WebAudio synth. No audio files, nothing to download, and it starts only
 * after a user gesture (browser policy).
 */
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.musicGain = null
    this.muted = false
    this.musicTimer = null
    this.chordIndex = 0
    this.ready = false
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.55
    this.master.connect(this.ctx.destination)

    const delay = this.ctx.createDelay(0.6)
    delay.delayTime.value = 0.28
    const feedback = this.ctx.createGain()
    feedback.gain.value = 0.22
    const wet = this.ctx.createGain()
    wet.gain.value = 0.25
    this.master.connect(delay)
    delay.connect(feedback)
    feedback.connect(delay)
    delay.connect(wet)
    wet.connect(this.ctx.destination)

    this.musicGain = this.ctx.createGain()
    this.musicGain.gain.value = 0.5
    this.musicGain.connect(this.master)
    this.ready = true
    this.startMusic()
  }

  setMuted(muted) {
    this.muted = muted
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.05)
  }

  tone({ freq = 440, dur = 0.15, type = 'sine', gain = 0.08, slide = 0, delay = 0, lowpass = null }) {
    if (!this.ready || this.muted) return
    const t = this.ctx.currentTime + delay
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur)
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    let node = osc
    if (lowpass) {
      const filter = this.ctx.createBiquadFilter()
      filter.type = 'lowpass'
      filter.frequency.value = lowpass
      node.connect(filter)
      node = filter
    }
    node.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + dur + 0.05)
  }

  noise({ dur = 0.2, gain = 0.05, delay = 0, freq = 1200 }) {
    if (!this.ready || this.muted) return
    const t = this.ctx.currentTime + delay
    const size = Math.floor(this.ctx.sampleRate * dur)
    const buffer = this.ctx.createBuffer(1, size, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < size; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / size)
    const src = this.ctx.createBufferSource()
    src.buffer = buffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.value = freq
    filter.Q.value = 0.8
    const g = this.ctx.createGain()
    g.gain.value = gain
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(t)
  }

  click() {
    this.tone({ freq: 680, dur: 0.05, type: 'triangle', gain: 0.035 })
  }

  hover() {
    this.tone({ freq: 940, dur: 0.035, type: 'sine', gain: 0.012 })
  }

  dice() {
    this.noise({ dur: 0.35, gain: 0.07, freq: 900 })
    for (let i = 0; i < 7; i++) {
      this.noise({ dur: 0.03, gain: 0.08, freq: 2400 + Math.random() * 1000, delay: 0.1 + i * 0.09 })
    }
  }

  hop() {
    this.tone({ freq: 420, dur: 0.08, type: 'sine', gain: 0.025, slide: 140 })
  }

  coin() {
    this.tone({ freq: 880, dur: 0.2, type: 'sine', gain: 0.05 })
    this.tone({ freq: 1320, dur: 0.25, type: 'sine', gain: 0.035, delay: 0.06 })
  }

  pay() {
    this.tone({ freq: 300, dur: 0.2, type: 'triangle', gain: 0.05, slide: -100 })
  }

  buy() {
    ;[523, 659, 784].forEach((f, i) => this.tone({ freq: f, dur: 0.3, type: 'triangle', gain: 0.05, delay: i * 0.07 }))
  }

  upgrade() {
    ;[392, 523, 659, 880].forEach((f, i) => this.tone({ freq: f, dur: 0.35, type: 'sine', gain: 0.04, delay: i * 0.06 }))
  }

  card() {
    this.noise({ dur: 0.25, gain: 0.035, freq: 1800 })
    this.tone({ freq: 520, dur: 0.15, type: 'sine', gain: 0.025, slide: 220 })
  }

  evolve() {
    ;[330, 392, 494, 587].forEach((f, i) =>
      this.tone({ freq: f, dur: 0.5, type: 'sine', gain: 0.018, delay: i * 0.09, lowpass: 1600 })
    )
  }

  error() {
    this.tone({ freq: 180, dur: 0.18, type: 'square', gain: 0.03 })
  }

  win() {
    const notes = [392, 523, 659, 784, 1046]
    notes.forEach((f, i) =>
      this.tone({ freq: f, dur: 0.6, type: 'triangle', gain: 0.055, delay: i * 0.12 })
    )
    this.tone({ freq: 784, dur: 1.2, type: 'sine', gain: 0.03, delay: 0.7 })
  }

  sleep() {
    this.tone({ freq: 220, dur: 0.3, type: 'sine', gain: 0.04, slide: -60 })
  }

  startMusic() {
    if (!this.ready || this.musicTimer) return
    const chords = [
      [130.81, 196.0, 261.63, 329.63],
      [110.0, 164.81, 261.63, 329.63],
      [174.61, 220.0, 293.66, 349.23],
      [146.83, 220.0, 293.66, 392.0]
    ]
    const play = () => {
      if (!this.ready || this.muted) return
      const chord = chords[this.chordIndex % chords.length]
      this.chordIndex++
      chord.forEach((freq, i) => {
        const osc = this.ctx.createOscillator()
        const gain = this.ctx.createGain()
        const filter = this.ctx.createBiquadFilter()
        osc.type = i === 0 ? 'triangle' : 'sine'
        osc.frequency.value = freq * (i === 2 ? 1.001 : 1)
        filter.type = 'lowpass'
        filter.frequency.value = 900
        const t = this.ctx.currentTime
        gain.gain.setValueAtTime(0.0001, t)
        gain.gain.linearRampToValueAtTime(i === 0 ? 0.028 : 0.018, t + 1.8)
        gain.gain.linearRampToValueAtTime(0.0001, t + 7.4)
        osc.connect(filter)
        filter.connect(gain)
        gain.connect(this.musicGain)
        osc.start(t)
        osc.stop(t + 7.6)
      })
      // sparse sparkle
      if (Math.random() < 0.65) {
        const scale = [523.25, 587.33, 659.25, 783.99, 880.0]
        this.tone({
          freq: scale[Math.floor(Math.random() * scale.length)],
          dur: 0.5,
          type: 'sine',
          gain: 0.012,
          delay: 2 + Math.random() * 3,
          lowpass: 2200
        })
      }
      this.musicTimer = setTimeout(play, 6000)
    }
    play()
  }

  stopMusic() {
    clearTimeout(this.musicTimer)
    this.musicTimer = null
  }
}

