input.content:
:root {
  --bg: #071b1c;
  --bg-deep: #041313;
  --panel: #0c2a28;
  --panel-2: #0a2322;
  --ink: #fff8e7;
  --ink-soft: #d7e7db;
  --muted: #93b0a3;
  --muted-2: #6f8f85;
  --lime: #b9f26b;
  --lime-soft: #d6ff8e;
  --gold: #ffd37a;
  --coral: #ff8d66;
  --sky: #6fdcf0;
  --violet: #c7a6ff;
  --line: rgba(214, 255, 142, 0.16);
  --line-strong: rgba(214, 255, 142, 0.32);
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
  --radius: 24px;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --font: 'Outfit Variable', 'Outfit', system-ui, -apple-system, sans-serif;
  --serif: 'Fraunces Variable', 'Fraunces', Georgia, serif;
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  height: 100dvh;
  overscroll-behavior: none;
  user-select: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible {
  outline: 2px solid var(--lime-soft);
  outline-offset: 3px;
}

.hidden {
  display: none !important;
}

#app {
  position: relative;
  width: 100%;
  height: 100dvh;
  overflow: hidden;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  background: #071b1c;
}

.vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 40%, rgba(1, 9, 10, 0.32) 75%, rgba(1, 7, 8, 0.7) 100%),
    linear-gradient(180deg, rgba(1, 9, 10, 0.35), transparent 18% 82%, rgba(1, 9, 10, 0.45));
}

/* ------------------------------------------------------------------ boot */
.boot {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-content: center;
  gap: 20px;
  justify-items: center;
  background: radial-gradient(circle at 50% 45%, #113c36, #041313 70%);
  transition: opacity 0.7s ease, visibility 0.7s;
}

.boot.hidden {
  display: grid !important;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.boot-mark {
  display: grid;
  grid-template-columns: repeat(2, 18px);
  gap: 6px;
}

.boot-mark span {
  width: 18px;
  height: 18px;
  border-radius: 5px;
  background: var(--lime);
  animation: bootPulse 1.1s ease-in-out infinite;
}

.boot-mark span:nth-child(2) {
  animation-delay: 0.15s;
}
.boot-mark span:nth-child(3) {
  animation-delay: 0.3s;
}
.boot-mark span:nth-child(4) {
  animation-delay: 0.45s;
}

.boot p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

@keyframes bootPulse {
  0%,
  100% {
    opacity: 0.3;
    transform: scale(0.86);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

/* ----------------------------------------------------------------- title */
.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
}

.title-screen {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: calc(14px + var(--safe-top)) 22px calc(18px + var(--safe-bottom));
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(2, 12, 13, 0.72) 0%, transparent 24%, transparent 58%, rgba(2, 12, 13, 0.82) 84%, rgba(2, 12, 13, 0.94) 100%);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.title-screen.leaving {
  opacity: 0;
  transform: scale(1.02);
  pointer-events: none;
}

.title-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  pointer-events: auto;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ink-soft);
  padding: 8px 13px;
  border: 1px solid rgba(214, 255, 142, 0.18);
  border-radius: 999px;
  background: rgba(5, 23, 23, 0.55);
  backdrop-filter: blur(10px);
}

.eyebrow i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 10px var(--lime);
}

.title-version {
  font-size: 10px;
  letter-spacing: 0.14em;
  color: var(--muted-2);
}

.title-hero {
  text-align: center;
  margin-top: auto;
  margin-bottom: 8vh;
  pointer-events: none;
}

.logo {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  filter: drop-shadow(0 18px 50px rgba(0, 0, 0, 0.55));
}

.logo-life {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 520;
  font-variation-settings: 'opsz' 100, 'SOFT' 60, 'WONK' 1;
  font-size: clamp(82px, 19vw, 172px);
  line-height: 0.74;
  letter-spacing: -0.04em;
  color: var(--ink);
  text-shadow: 0 2px 0 rgba(255, 255, 255, 0.08), 0 30px 60px rgba(0, 0, 0, 0.4);
}

.logo-row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 8px;
}

.logo-rule {
  display: block;
  width: clamp(30px, 9vw, 90px);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(185, 242, 107, 0.8));
}

.logo-row .logo-rule:last-child {
  transform: scaleX(-1);
}

.logo-estate {
  font-family: var(--font);
  font-size: clamp(19px, 4.6vw, 40px);
  font-weight: 600;
  letter-spacing: 0.4em;
  margin-right: -0.4em;
  text-transform: uppercase;
  color: var(--lime);
  text-shadow: 0 0 30px rgba(185, 242, 107, 0.3);
}

.tagline {
  margin: 22px 0 0;
  font-size: clamp(11px, 2.4vw, 13px);
  font-weight: 400;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-soft);
  text-shadow: 0 4px 24px rgba(0, 0, 0, 0.6);
}

.title-bottom {
  pointer-events: auto;
  width: min(440px, 100%);
  margin: 0 auto;
}

.title-actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.title-actions .btn-primary {
  height: 58px;
  font-size: 15px;
}

.title-actions .btn-ghost,
.title-actions .btn-quiet {
  height: 46px;
}

.title-actions .btn-ghost {
  order: -1;
}

.title-foot {
  margin: 16px 0 0;
  text-align: center;
  font-size: 9px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted-2);
}

.title-foot span {
  margin: 0 5px;
  color: rgba(214, 255, 142, 0.35);
}

/* ------------------------------------------------------------------ buttons */
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  height: 50px;
  border-radius: 16px;
  padding: 0 22px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transition: transform 0.16s ease, background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.btn:active {
  transform: scale(0.975);
}

.btn-primary {
  color: #0a2018;
  background: linear-gradient(135deg, #d6ff8e 0%, #9fe356 55%, #7bd247 100%);
  box-shadow: 0 12px 30px rgba(143, 220, 86, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.55);
}

.btn-primary:hover {
  box-shadow: 0 16px 40px rgba(143, 220, 86, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.6);
}

.btn-ghost {
  color: var(--ink);
  background: rgba(9, 37, 35, 0.72);
  border: 1px solid rgba(214, 255, 142, 0.24);
  backdrop-filter: blur(12px);
}

.btn-ghost:hover {
  border-color: var(--line-strong);
  background: rgba(14, 50, 46, 0.8);
}

.btn-quiet {
  color: var(--ink-soft);
  background: rgba(7, 28, 27, 0.42);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
}

.btn-quiet:hover {
  color: var(--ink);
  border-color: rgba(255, 255, 255, 0.16);
}

.btn-danger {
  color: #ffd9cf;
  border: 1px solid rgba(255, 141, 102, 0.32);
  background: rgba(72, 28, 22, 0.4);
}

.btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
  filter: saturate(0.4);
  box-shadow: none;
}

/* --------------------------------------------------------------------- HUD */
.game-ui {
  position: fixed;
  inset: 0;
  z-index: 15;
  pointer-events: none;
}

.hud-top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: calc(9px + var(--safe-top)) 14px 20px;
  pointer-events: auto;
  background: linear-gradient(180deg, rgba(2, 12, 13, 0.82) 0%, rgba(2, 12, 13, 0.45) 55%, transparent 100%);
}

.brand-mini {
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--ink);
  white-space: nowrap;
}

.brand-mini span {
  margin-left: 5px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--lime);
}

.round-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 30px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid rgba(214, 255, 142, 0.18);
  background: rgba(5, 23, 23, 0.68);
  backdrop-filter: blur(10px);
  font-size: 9px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-soft);
  white-space: nowrap;
}

.round-pill span + span {
  padding-left: 8px;
  border-left: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--lime-soft);
}

.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 13px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(5, 23, 23, 0.68);
  backdrop-filter: blur(10px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  flex: none;
}

.icon-btn span {
  width: 14px;
  height: 1.5px;
  border-radius: 2px;
  background: var(--ink-soft);
}

.icon-btn:hover {
  border-color: var(--line-strong);
}

.player-rail {
  position: absolute;
  top: calc(58px + var(--safe-top));
  left: 12px;
  right: 12px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
  pointer-events: auto;
  max-width: 760px;
  margin: 0 auto;
}

.player-card {
  --pc: var(--lime);
  position: relative;
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  height: 48px;
  padding: 6px 8px;
  border-radius: 14px;
  background: rgba(5, 24, 24, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(12px);
  transition: transform 0.2s ease, border-color 0.25s ease, background 0.25s ease, box-shadow 0.25s ease;
  overflow: hidden;
}

.player-card::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 2px;
  background: var(--pc);
  opacity: 0.5;
}

.player-card.active {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--pc) 62%, transparent);
  background: linear-gradient(180deg, rgba(22, 60, 52, 0.9), rgba(7, 31, 29, 0.86));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--pc) 22%, transparent), 0 10px 26px rgba(0, 0, 0, 0.26);
}

.player-card.active::before {
  opacity: 1;
  box-shadow: 0 0 14px var(--pc);
}

.player-card.bankrupt {
  opacity: 0.4;
  filter: grayscale(0.8);
}

.pc-token {
  flex: none;
  width: 29px;
  height: 29px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--pc) 17%, transparent);
  border: 1px solid color-mix(in srgb, var(--pc) 32%, transparent);
  color: var(--pc);
  font-size: 13px;
  line-height: 1;
}

.pc-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
}

.pc-name {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pc-cash {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.pc-nw {
  display: none;
  font-size: 8px;
  letter-spacing: 0.06em;
  color: var(--muted-2);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.player-card .pc-turn-dot {
  position: absolute;
  top: 6px;
  right: 7px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--pc);
  box-shadow: 0 0 8px var(--pc);
  opacity: 0;
}

.player-card.active .pc-turn-dot {
  opacity: 1;
  animation: dotPulse 1.6s ease-in-out infinite;
}

@keyframes dotPulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 1;
  }
  50% {
    transform: scale(1.5);
    opacity: 0.55;
  }
}

/* ------------------------------------------------------------------- dock */
.dock {
  position: absolute;
  left: 50%;
  bottom: calc(12px + var(--safe-bottom));
  transform: translateX(-50%);
  width: min(680px, calc(100% - 24px));
  min-height: 70px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 10px 9px 18px;
  border-radius: 22px;
  background: linear-gradient(180deg, rgba(11, 42, 39, 0.92), rgba(5, 25, 24, 0.94));
  border: 1px solid rgba(214, 255, 142, 0.17);
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(16px);
  pointer-events: auto;
}

.turn-copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.turn-kicker {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--lime);
}

.turn-copy strong {
  font-size: 12px;
  font-weight: 500;
  line-height: 1.3;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.turn-copy strong.thinking::after {
  content: '…';
  display: inline-block;
  width: 12px;
  animation: think 1.2s steps(4, end) infinite;
  overflow: hidden;
  vertical-align: bottom;
}

@keyframes think {
  0% {
    width: 0;
  }
  100% {
    width: 14px;
  }
}

.roll-btn {
  flex: none;
  height: 52px;
  min-width: 136px;
  padding: 0 20px;
  border-radius: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #092014;
  background: linear-gradient(135deg, #e2ff9f 0%, #b9f26b 48%, #8ddd4f 100%);
  box-shadow: 0 10px 24px rgba(143, 220, 86, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.62);
  transition: transform 0.16s ease, box-shadow 0.2s ease, opacity 0.2s ease;
}

.roll-btn:not(:disabled):hover {
  transform: translateY(-1px);
  box-shadow: 0 14px 30px rgba(143, 220, 86, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.roll-btn:not(:disabled):active {
  transform: scale(0.985);
}

.roll-btn:disabled {
  opacity: 0.4;
  color: var(--ink-soft);
  background: rgba(14, 48, 44, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: none;
}

.roll-glyph {
  font-size: 22px;
  line-height: 1;
  transform: translateY(-1px);
}

.view-tools {
  position: absolute;
  right: 12px;
  bottom: calc(96px + var(--safe-bottom));
  display: flex;
  flex-direction: column;
  gap: 7px;
  pointer-events: auto;
}

.tool-btn {
  width: 40px;
  height: 40px;
  border-radius: 13px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(5, 24, 24, 0.72);
  color: var(--ink-soft);
  font-size: 18px;
  display: grid;
  place-items: center;
  backdrop-filter: blur(10px);
  transition: border-color 0.2s ease, color 0.2s ease, transform 0.16s ease;
}

.tool-btn:hover {
  color: var(--ink);
  border-color: var(--line-strong);
}

.tool-btn:active {
  transform: scale(0.94);
}

/* --------------------------------------------------------------- tile card */
.tile-card {
  position: absolute;
  left: 14px;
  bottom: calc(96px + var(--safe-bottom));
  width: 286px;
  padding: 15px 16px 16px;
  border-radius: 19px;
  background: linear-gradient(175deg, rgba(14, 49, 44, 0.96), rgba(5, 25, 24, 0.96));
  border: 1px solid rgba(214, 255, 142, 0.17);
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px);
  pointer-events: auto;
  animation: cardIn 0.28s ease both;
}

@keyframes cardIn {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.mini-close {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 28px;
  height: 28px;
  border-radius: 9px;
  color: var(--muted);
  font-size: 17px;
  line-height: 1;
  display: grid;
  place-items: center;
}

.mini-close:hover {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.06);
}

.tile-eyebrow {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--district, var(--lime));
  margin-bottom: 5px;
}

.tile-eyebrow i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--district, var(--lime));
  box-shadow: 0 0 8px var(--district, var(--lime));
}

.tile-name {
  margin: 0;
  font-family: var(--serif);
  font-size: 24px;
  font-weight: 550;
  line-height: 1.05;
  letter-spacing: -0.01em;
  color: var(--ink);
  padding-right: 22px;
}

.tile-desc {
  margin: 7px 0 0;
  font-size: 11px;
  line-height: 1.45;
  color: var(--muted);
}

.tile-stats {
  display: flex;
  gap: 14px;
  margin-top: 11px;
  padding-top: 11px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

.tile-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tile-stat span {
  font-size: 7px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted-2);
}

.tile-stat strong {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.tile-owner {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 10px;
  padding: 4px 9px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--pc, var(--lime)) 13%, transparent);
  border: 1px solid color-mix(in srgb, var(--pc, var(--lime)) 28%, transparent);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--pc, var(--lime));
}

/* ------------------------------------------------------------------- modals */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  background: rgba(2, 11, 12, 0.62);
  backdrop-filter: blur(7px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s ease, visibility 0.25s;
}

.modal-backdrop.visible {
  opacity: 1;
  visibility: visible;
}

.modal-root {
  position: fixed;
  inset: 0;
  z-index: 51;
  display: grid;
  place-items: center;
  padding: 16px;
  pointer-events: none;
}

.modal {
  pointer-events: auto;
  position: relative;
  width: min(560px, 100%);
  max-height: calc(100dvh - 32px - var(--safe-top) - var(--safe-bottom));
  overflow: auto;
  overscroll-behavior: contain;
  padding: 24px;
  border-radius: 28px;
  background:
    radial-gradient(120% 90% at 50% 0%, rgba(46, 102, 82, 0.24), transparent 60%),
    linear-gradient(180deg, #0e312e 0%, #081f1e 100%);
  border: 1px solid rgba(214, 255, 142, 0.16);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  animation: modalIn 0.32s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  scrollbar-width: thin;
  scrollbar-color: rgba(185, 242, 107, 0.25) transparent;
}

.modal::-webkit-scrollbar {
  width: 5px;
}
.modal::-webkit-scrollbar-thumb {
  background: rgba(185, 242, 107, 0.25);
  border-radius: 4px;
}

@keyframes modalIn {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.modal-accent {
  position: absolute;
  top: 0;
  left: 24px;
  right: 24px;
  height: 2px;
  border-radius: 0 0 4px 4px;
  background: linear-gradient(90deg, transparent, var(--accent, var(--lime)), transparent);
  opacity: 0.75;
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}

.modal-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--accent, var(--lime));
  margin-bottom: 7px;
}

.modal-eyebrow i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent, var(--lime));
  box-shadow: 0 0 8px var(--accent, var(--lime));
}

.modal h2 {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(26px, 5vw, 34px);
  font-weight: 550;
  line-height: 1.05;
  letter-spacing: -0.015em;
  color: var(--ink);
}

.modal h3 {
  margin: 0 0 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.modal-sub {
  margin: 7px 0 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--muted);
}

.modal-close {
  flex: none;
  width: 36px;
  height: 36px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  font-size: 20px;
  line-height: 1;
  display: grid;
  place-items: center;
}

.modal-close:hover {
  color: var(--ink);
  border-color: rgba(255, 255, 255, 0.16);
}

.modal-body {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.stat-box {
  padding: 10px 11px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.stat-box span {
  display: block;
  font-size: 7px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted-2);
  margin-bottom: 3px;
}

.stat-box strong {
  font-size: 15px;
  font-weight: 700;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.stat-box strong.accent {
  color: var(--accent, var(--lime));
}

.district-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent, var(--lime));
  border: 1px solid color-mix(in srgb, var(--accent, var(--lime)) 30%, transparent);
  background: color-mix(in srgb, var(--accent, var(--lime)) 10%, transparent);
}

/* property modal */
.property-price-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  border-radius: 16px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 12%, transparent), transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 22%, transparent);
}

.property-price-row span {
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.property-price-row strong {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.life-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 14px;
  border-radius: 18px;
  background: rgba(3, 17, 17, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.life-grid {
  display: grid;
  gap: 4px;
  padding: 9px;
  border-radius: 14px;
  background: #061a19;
  border: 1px solid rgba(214, 255, 142, 0.12);
  grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr));
  width: min(230px, 54vw);
  aspect-ratio: 1;
  flex: none;
}

.life-cell {
  position: relative;
  padding: 0;
  border-radius: 4px;
  background: #10352f;
  border: 1px solid rgba(255, 255, 255, 0.025);
  transition: background 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
  aspect-ratio: 1;
}

.life-cell.alive {
  background: var(--district, var(--lime));
  border-color: color-mix(in srgb, var(--district, var(--lime)) 70%, white);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35), 0 0 9px color-mix(in srgb, var(--district, var(--lime)) 35%, transparent);
}

.life-cell.selectable {
  cursor: pointer;
  outline: 1px dashed rgba(185, 242, 107, 0.25);
  outline-offset: -2px;
}

.life-cell.selectable:hover {
  background: rgba(185, 242, 107, 0.25);
}

.life-cell.selected {
  background: var(--lime);
  border-color: #efffd2;
  box-shadow: 0 0 12px var(--lime);
  transform: scale(0.9);
}

.life-side {
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
}

.life-side .big {
  font-size: 30px;
  font-weight: 800;
  line-height: 1;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.life-side .label {
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted-2);
}

.life-side .hint {
  font-size: 10px;
  line-height: 1.4;
  color: var(--muted);
  max-width: 130px;
}

.life-edit-note {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 12px;
  background: rgba(185, 242, 107, 0.08);
  border: 1px solid rgba(185, 242, 107, 0.18);
  font-size: 10px;
  color: var(--lime-soft);
}

.action-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.action-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 11px 13px;
  border-radius: 15px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.035);
  text-align: left;
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.14s ease;
}

.action-btn:not(:disabled):hover {
  border-color: rgba(214, 255, 142, 0.25);
  background: rgba(214, 255, 142, 0.06);
}

.action-btn:not(:disabled):active {
  transform: scale(0.99);
}

.action-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.action-icon {
  flex: none;
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: rgba(185, 242, 107, 0.1);
  border: 1px solid rgba(185, 242, 107, 0.16);
  color: var(--lime);
  font-size: 18px;
}

.action-icon.gold {
  color: var(--gold);
  background: rgba(255, 211, 122, 0.09);
  border-color: rgba(255, 211, 122, 0.18);
}

.action-icon.coral {
  color: var(--coral);
  background: rgba(255, 141, 102, 0.09);
  border-color: rgba(255, 141, 102, 0.18);
}

.action-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.action-text strong {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
}

.action-text span {
  font-size: 10px;
  line-height: 1.35;
  color: var(--muted);
}

.action-cost {
  margin-left: auto;
  font-size: 12px;
  font-weight: 700;
  color: var(--lime-soft);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.modal-actions {
  display: flex;
  gap: 9px;
  margin-top: 4px;
}

.modal-actions .btn {
  flex: 1;
  height: 48px;
}

/* cards */
.card-modal {
  width: min(380px, 100%);
  text-align: center;
  padding: 26px 24px 24px;
  overflow: hidden;
}

.card-modal::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 12%, color-mix(in srgb, var(--accent) 22%, transparent), transparent 52%),
    repeating-linear-gradient(135deg, transparent 0 12px, rgba(255, 255, 255, 0.012) 12px 13px);
  pointer-events: none;
}

.card-icon {
  position: relative;
  width: 76px;
  height: 76px;
  margin: 0 auto 16px;
  border-radius: 24px;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-size: 40px;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, rgba(6, 27, 26, 0.8));
  border: 1px solid color-mix(in srgb, var(--accent) 36%, transparent);
  box-shadow: 0 0 40px color-mix(in srgb, var(--accent) 18%, transparent);
}

.card-deck {
  position: relative;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 8px;
}

.card-title {
  position: relative;
  margin: 0;
  font-family: var(--serif);
  font-size: 32px;
  font-weight: 550;
  line-height: 1.05;
  color: var(--ink);
}

.card-text {
  position: relative;
  margin: 12px auto 20px;
  max-width: 290px;
  font-size: 12px;
  line-height: 1.6;
  color: var(--ink-soft);
}

.card-modal .btn {
  position: relative;
  width: 100%;
}

/* setup modal */
.token-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.token-choice {
  padding: 11px 6px 9px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.03);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  transition: border-color 0.2s ease, background 0.2s ease, transform 0.16s ease;
}

.token-choice:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--tc) 40%, transparent);
}

.token-choice.selected {
  border-color: var(--tc);
  background: color-mix(in srgb, var(--tc) 12%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--tc) 35%, transparent);
}

.token-choice .tc-orb {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--tc);
  font-size: 17px;
  background: color-mix(in srgb, var(--tc) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--tc) 30%, transparent);
}

.token-choice .tc-name {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.segmented {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  padding: 4px;
  border-radius: 14px;
  background: rgba(4, 19, 19, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.segment {
  padding: 10px 8px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  transition: background 0.2s ease, color 0.2s ease;
}

.segment.selected {
  background: rgba(185, 242, 107, 0.14);
  color: var(--lime-soft);
  box-shadow: inset 0 0 0 1px rgba(185, 242, 107, 0.18);
}

.difficulty-note {
  margin: 9px 0 0;
  font-size: 10px;
  line-height: 1.45;
  color: var(--muted);
  min-height: 28px;
}

/* how to play */
.how-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.how-step {
  display: flex;
  gap: 12px;
  padding: 12px 13px;
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.055);
}

.how-num {
  flex: none;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-size: 16px;
  color: var(--lime);
  background: rgba(185, 242, 107, 0.09);
  border: 1px solid rgba(185, 242, 107, 0.16);
}

.how-step strong {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
  margin-bottom: 3px;
}

.how-step p {
  margin: 0;
  font-size: 10.5px;
  line-height: 1.5;
  color: var(--muted);
}

.how-note {
  padding: 12px 14px;
  border-radius: 14px;
  background: rgba(185, 242, 107, 0.06);
  border: 1px solid rgba(185, 242, 107, 0.14);
  font-size: 10.5px;
  line-height: 1.55;
  color: var(--lime-soft);
}

/* settings */
.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 2px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.setting-row:last-child {
  border-bottom: 0;
}

.setting-copy strong {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
}

.setting-copy span {
  display: block;
  margin-top: 2px;
  font-size: 10px;
  color: var(--muted);
}

.switch {
  position: relative;
  width: 46px;
  height: 27px;
  flex: none;
}

.switch input {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  cursor: pointer;
}

.switch span {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: background 0.2s ease, border-color 0.2s ease;
  pointer-events: none;
}

.switch span::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: #a9beb2;
  transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.2s ease;
}

.switch input:checked + span {
  background: rgba(185, 242, 107, 0.22);
  border-color: rgba(185, 242, 107, 0.35);
}

.switch input:checked + span::after {
  transform: translateX(19px);
  background: var(--lime);
}

.switch input:focus-visible + span {
  outline: 2px solid var(--lime-soft);
  outline-offset: 2px;
}

/* pause */
.pause-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pause-list .btn {
  width: 100%;
  height: 50px;
}

/* victory */
.victory-modal {
  text-align: center;
  width: min(480px, 100%);
}

.victory-mark {
  width: 92px;
  height: 92px;
  margin: 0 auto 18px;
  border-radius: 28px;
  display: grid;
  place-items: center;
  font-size: 42px;
  color: var(--gold);
  background: radial-gradient(circle at 50% 30%, rgba(255, 211, 122, 0.24), rgba(255, 211, 122, 0.04));
  border: 1px solid rgba(255, 211, 122, 0.3);
  box-shadow: 0 0 60px rgba(255, 211, 122, 0.14);
}

.victory-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--gold);
}

.victory-name {
  margin: 7px 0 0;
  font-family: var(--serif);
  font-size: clamp(38px, 8vw, 54px);
  font-weight: 550;
  line-height: 1;
  color: var(--ink);
}

.victory-reason {
  margin: 10px auto 20px;
  max-width: 320px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--muted);
}

.victory-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 18px 0;
}

.victory-stats .stat-box strong {
  font-size: 16px;
}

.victory-table {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 16px 0 20px;
  text-align: left;
}

.victory-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 10px;
  align-items: center;
  padding: 9px 12px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
  font-size: 11px;
}

.victory-row.active {
  background: rgba(185, 242, 107, 0.08);
  border: 1px solid rgba(185, 242, 107, 0.16);
}

.victory-row .vr-name {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--ink-soft);
}

.victory-row .vr-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--pc);
}

.victory-row .vr-cash {
  font-weight: 700;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.victory-row .vr-nw {
  font-size: 9px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------------ toasts */
.toast-stack {
  position: fixed;
  top: calc(120px + var(--safe-top));
  right: 14px;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 7px;
  width: min(340px, calc(100vw - 28px));
  pointer-events: none;
}

.toast {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  padding: 10px 13px;
  border-radius: 13px;
  background: rgba(6, 28, 27, 0.94);
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-left: 2px solid var(--lime);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.3);
  font-size: 10.5px;
  line-height: 1.45;
  color: var(--ink-soft);
  animation: toastIn 0.3s ease both;
  backdrop-filter: blur(12px);
}

.toast.out {
  animation: toastOut 0.35s ease forwards;
}

.toast.good {
  border-left-color: var(--lime);
}
.toast.bad {
  border-left-color: var(--coral);
}
.toast.card {
  border-left-color: var(--violet);
}
.toast.life {
  border-left-color: var(--sky);
}
.toast.end {
  border-left-color: var(--gold);
}

.toast b {
  color: var(--ink);
  font-weight: 600;
}

@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateX(18px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes toastOut {
  to {
    opacity: 0;
    transform: translateX(18px);
  }
}

/* ---------------------------------------------------------------------- fx */
.fx-layer {
  position: fixed;
  inset: 0;
  z-index: 30;
  pointer-events: none;
  overflow: hidden;
}

.float-text {
  position: absolute;
  transform: translate(-50%, -50%);
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.02em;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.7), 0 0 22px currentColor;
  animation: floatUp 1.45s cubic-bezier(0.15, 0.7, 0.3, 1) forwards;
  white-space: nowrap;
}

@keyframes floatUp {
  0% {
    opacity: 0;
    transform: translate(-50%, -30%) scale(0.7);
  }
  15% {
    opacity: 1;
    transform: translate(-50%, -60%) scale(1.05);
  }
  35% {
    transform: translate(-50%, -85%) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -190%) scale(0.92);
  }
}

.spark {
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 8px currentColor;
  animation: sparkOut 0.9s ease-out forwards;
}

@keyframes sparkOut {
  from {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
  to {
    opacity: 0;
    transform: translate(calc(-50% + var(--dx)), calc(-50% + var(--dy))) scale(0.2);
  }
}

/* --------------------------------------------------------------- responsive */
@media (min-width: 760px) {
  .pc-nw {
    display: block;
  }

  .player-card {
    height: 52px;
    padding: 7px 10px;
  }

  .pc-name {
    font-size: 9.5px;
  }

  .pc-cash {
    font-size: 13px;
  }

  .title-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .title-actions .btn-primary,
  .title-actions .btn-ghost {
    grid-column: 1 / -1;
  }

  .title-actions .btn-ghost {
    order: 0;
  }

  .title-actions .btn-quiet {
    grid-column: span 1;
  }

  .title-hero {
    margin-bottom: 4vh;
  }

  .modal-root {
    padding: 24px;
  }

  .dock {
    bottom: calc(18px + var(--safe-bottom));
  }

  .tile-card {
    left: 22px;
    bottom: calc(112px + var(--safe-bottom));
  }

  .view-tools {
    right: 22px;
    bottom: calc(112px + var(--safe-bottom));
  }
}

@media (max-width: 430px) {
  .hud-top {
    padding-left: 12px;
    padding-right: 12px;
  }

  .brand-mini {
    font-size: 12px;
  }

  .round-pill {
    padding: 0 10px;
    gap: 6px;
    font-size: 8px;
  }

  .round-pill span + span {
    padding-left: 6px;
  }

  .player-rail {
    left: 8px;
    right: 8px;
    gap: 5px;
  }

  .player-card {
    gap: 5px;
    padding: 5px 6px;
    height: 45px;
    border-radius: 12px;
  }

  .pc-token {
    width: 25px;
    height: 25px;
    border-radius: 8px;
    font-size: 11px;
  }

  .pc-name {
    font-size: 8px;
  }

  .pc-cash {
    font-size: 11px;
  }

  .dock {
    min-height: 66px;
    padding: 8px 8px 8px 14px;
    border-radius: 20px;
  }

  .turn-copy strong {
    font-size: 11px;
  }

  .roll-btn {
    height: 48px;
    min-width: 120px;
    padding: 0 15px;
    font-size: 12px;
  }

  .tile-card {
    width: calc(100% - 28px);
    left: 14px;
    bottom: calc(90px + var(--safe-bottom));
  }

  .life-grid {
    width: min(210px, 48vw);
  }

  .modal {
    padding: 20px;
    border-radius: 24px;
  }

  .card-modal {
    padding: 24px 20px 20px;
  }
}

@media (max-height: 700px) {
  .title-hero {
    margin-bottom: 2vh;
  }

  .logo-life {
    font-size: clamp(62px, 15vw, 120px);
  }

  .tagline {
    margin-top: 14px;
  }

  .title-actions .btn-primary {
    height: 52px;
  }

  .title-actions .btn-ghost,
  .title-actions .btn-quiet {
    height: 42px;
  }
}

@media (orientation: landscape) and (max-height: 560px) {
  .title-screen {
    padding-top: calc(8px + var(--safe-top));
    padding-bottom: calc(8px + var(--safe-bottom));
  }

  .title-hero {
    margin: 0;
    position: absolute;
    left: 26px;
    top: 50%;
    transform: translateY(-50%);
    text-align: left;
    align-items: flex-start;
    max-width: 42%;
  }

  .logo {
    align-items: flex-start;
  }

  .logo-row {
    justify-content: flex-start;
  }

  .logo-row .logo-rule {
    display: none;
  }

  .tagline {
    text-align: left;
    font-size: 10px;
  }

  .title-bottom {
    margin-left: auto;
    width: min(320px, 46%);
    margin-top: auto;
  }

  .title-actions .btn-primary,
  .title-actions .btn-ghost {
    height: 42px;
    font-size: 11px;
  }

  .title-actions .btn-quiet {
    height: 36px;
    font-size: 10px;
  }

  .title-foot {
    margin-top: 8px;
  }

  .player-rail {
    max-width: 560px;
  }

  .dock {
    width: min(560px, calc(100% - 200px));
    left: 50%;
  }

  .tile-card {
    width: 250px;
    left: 12px;
    bottom: crc(80px + var(--safe-bottom));
  }

  .life-wrap {
    gap: 12px;
    padding: 9px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

